contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test that calling Deposit with a given amount increases this contract's recorded balance by exactly that amount
    // and Deposit does not revert. We send Ether from this contract to c, so require this contract has enough balance.
    function run(uint depositAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt);

        // Read recorded balance before deposit
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // Call Deposit sending depositAmt wei and capture whether it reverted
        bool reverted;
        c.Deposit{value: depositAmt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read recorded balance after deposit
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // If Deposit did not revert then recorded balance increased exactly by depositAmt
        // (use addition on the RHS to avoid underflow in the assertion)
        assert(reverted || balAfter == balBefore + depositAmt);
    }

    receive() external payable {}
}

